function cover(href) {
    var m = String(href).match(/\/(\d+)\/?$/);
    if (!m) return "";
    var id = m[1];
    var p = id.length <= 3 ? "0" : id.slice(0, -3);
    return "https://www.deqixss.com/files/article/image/" + p + "/" + id + "/" + id + "s.jpg";
}

function words(html) {
    var m = String(html).match(/towan\('(\d+)'\)/);
    if (m) return m[1];
    return String(html).replace(/<[^>]+>/g, "").replace(/字数[：:]/g, "").trim();
}

ruleContent.content:
@js:
var url = String(baseUrl);
var match = url.match(/\/(\d+)\/(\d+)\.html/);
var content = '';
if (match) {
    var origin = url.match(/(https?:\/\/[^\/]+)/)[1];
    var jsUrl = origin + '/scripts/chapter.js.php?aid=' + match[1] + '&cid=' + match[2] + '&referrer=' + encodeURIComponent(url);
    var scriptStr = java.ajax(jsUrl);
    var token = scriptStr.match(/chapterToken\s*=\s*['"]([^'"]+)['"]/);
    var ts = scriptStr.match(/timestamp\s*=\s*['"]?([^'";\s]+)/);
    var nc = scriptStr.match(/nonce\s*=\s*['"]([^'"]+)['"]/);
    if (token && ts && nc) {
        var ajaxUrl = origin + '/modules/article/ajax2.php?aid=' + match[1] + '&cid=' + match[2] + '&token=' + token[1] + '&timestamp=' + ts[1] + '&nonce=' + nc[1];
        var opt = JSON.stringify({
            "charset": "gbk",
            "headers": {
                "X-Requested-With": "XMLHttpRequest",
                "Referer": url
            }
        });
        var res = java.ajax(ajaxUrl + ',' + opt);
        try {
            content = JSON.parse(res).data.content;
        } catch (e) {}
    }
}
content ? content : java.getString('#rtext@html');

ruleContent.replaceRegex:
@js:
const FILTER_RULES = [
  /更新不易.+?看最新章节！/g,
  /更新不易.+?看最新无错章节！/g, 
  /更新不易.+?最新小说章节！/g,
  /速.?读.?谷/g, 
  /本章节未完.+?请订阅/g,
  /↑返回顶部↑/g,
  /[（(]本章.+?完[）)]/g,
  /^(?=.*[1-9])(?=.*章).+\n/,
]

for(let reg of FILTER_RULES){
	result = result.replace(reg, "")
}
result;

exploreUrl:
@js:
sort = cache.getFile('KuwoNovels');
if(sort==null){
var fk = sk = 1,
sort1 = [],
sort2 = [];
push=(title,url,type1,type2)=>{
		json = JSON.stringify({
				title: title,
				url: url?url:"",
				style: {
						layout_flexGrow: 1,
						layout_flexBasisPercent: type1
					}
			});
		return  eval('sort'+type2+'.push(json)');
	}
$$=(freetype,category_id,fk,sk)=>`https://appi.kuwo.cn/novels/api/book/category/${freetype}?category_id=${category_id}&fk=${fk}&sk=${sk}&pi={{page}\}&ps=20`;

JSON.parse(java.ajax('https://appi.kuwo.cn/novels/api/book/categories')).data.map($=>{
		freetype = $.freetype
		if(freetype==3)return;

		push(''+$.freetype_name+'', null, 1, freetype);
		$.categories.map($=>{
				category_id = $.category_id
				push(''+$.category_name+'', $$(freetype,category_id,sk,fk), 1, freetype);
				["综合", "热门", "最新"].map((title,sk)=>{
						sk++
						['['+title+']', '完结', '连载'].map((title,fk)=>{
								fk++
								push(title, $$(freetype,category_id,sk,fk), 0.25, freetype);
							});
					});
			});
	});
sort = sort1.concat(sort2);
cache.putFile('KuwoNovels', sort, 6E6);
}
'['+sort.toString()+']'

