@js:(function(){
var url='';try{url=String(baseUrl||'');}catch(e){}
if(!url){try{url=String(src||'');}catch(e2){}}
var m=url.match(/\/book\/(\d+)\/(\d+)\.html/);
if(!m)return '<p>无法解析章节地址</p>';
var bid=m[1],cid=m[2];
var base='https://book.washai.net';
function fetch(api,isPost,body){
var tk='';try{tk=String(java.getCookie(base,'novel_browser_token')||'');}catch(e){}
var H={'X-Browser-Token':tk,'X-Requested-With':'XMLHttpRequest','Referer':base+'/book/'+bid+'/'+cid+'.html','Origin':base,'Accept':'application/json, text/javascript, */*; q=0.01'};
var opt={headers:H};
if(isPost){opt.method='POST';opt.body=body;opt.headers['Content-Type']='application/x-www-form-urlencoded;charset=UTF-8';}
try{return String(java.ajax(api+','+JSON.stringify(opt))||'');}catch(e){return '';}
}
function clean(h){h=String(h||'');h=h.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<style[\s\S]*?<\/style>/gi,'');return h;}
try{
var tk='';try{tk=String(java.getCookie(base,'novel_browser_token')||'');}catch(e){}
if(!tk){try{java.ajax(base+'/book/'+bid+'/'+cid+'.html');}catch(e2){}}
var raw=fetch(base+'/book/queryReadPage?bookId='+bid+'&bookIndexId='+cid+'&contentFormat=html',false,'');
var j=JSON.parse(raw);
if(j.code!==200||!j.data)return '<p>正文加载失败,请刷新重试</p>';
var data=j.data;
if(data.needBuy)return '<p>此章节为VIP章节,需要订阅后阅读</p>';
if(data.readLocked){
var chRaw=fetch(base+'/book/read/challenge',true,'bookId='+bid+'&bookIndexId='+cid);
var ch=JSON.parse(chRaw);
if(ch.code!==200||!ch.data||!ch.data.challenge)return '<p>正文验证失败,请刷新重试</p>';
var waitMs=parseInt(ch.data.waitMs||0,10);if(waitMs>0&&waitMs<5000){var end=Date.now()+waitMs;while(Date.now()<end){}}
var tk2='';try{tk2=String(java.getCookie(base,'novel_browser_token')||'');}catch(e){}
var input='go-novel/read-gate-proof/v1'+String.fromCharCode(0)+ch.data.challenge+String.fromCharCode(0)+tk2;
var b64=String(java.digestBase64Str(input,'SHA-256')||'');
var proof=b64.replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/g,'');
var ubody='bookId='+bid+'&bookIndexId='+cid+'&challenge='+encodeURIComponent(ch.data.challenge)+'&proof='+encodeURIComponent(proof);
fetch(base+'/book/read/unlock',true,ubody);
raw=fetch(base+'/book/queryReadPage?bookId='+bid+'&bookIndexId='+cid+'&contentFormat=html',false,'');
try{var j2=JSON.parse(raw);if(j2.code===200&&j2.data)data=j2.data;}catch(e3){}
}
var html=clean(data.contentHtml||data.content||'');
return html||'<p>本章暂无内容</p>';
}catch(err){return '<p>正文解析异常:'+String(err&&err.message?err.message:err)+'</p>';}
})()

